import {systemLogo} from '/core.js';
import {bindMetricDrilldowns} from '/workspace-tools.js';
import {temporaryPasswordView,actionMenu,appearanceActions,uiIcon,api,applyTypography,bindLogin,cycleLocale,cycleTheme,esc,eventSource,fmtDate,fmtDateTime,downloadUrl,humanEvent,initLocale,initTheme,langButton,loginView,md,modal,setToken,t,themeIcon,toast,uiStatus} from '/core.js';
import {renderContent,renderLiveResults,renderQaBoard,renderIdeasBoard} from '/renderer.js';
import {activitySpec} from '/capability-registry.js';

initTheme();initLocale();
const app=document.querySelector('#app');
const state={user:null,data:null,brand:'Training Engine ONE',settings:null,notifications:[],unread:0,transcript:null,learningTools:null,stopEvents:null,timerId:null,selectedClass:Number(localStorage.getItem('training_engine_student_live_class')||0)};
const ntext=(key,n)=>t(key,{n:Number(n)||0});
const mergeTypography=(base={},override={})=>{if(base?.version===2)return base;const out=structuredClone(base||{});for(const k of ['ui','presentation','title','body'])out[k]={...(out[k]||{}),...(override?.[k]||{})};return out};
async function boot(){const me=await api('/api/me').catch(()=>({user:null}));if(!me.user||me.user.role!=='student')return showLogin();state.user=me.user;if(me.user.must_change_password)return temporaryPasswordView(app,me.user,async u=>{state.user=u;await enter()});await enter()}
function showLogin(){setToken('');app.innerHTML=loginView({role:'student',title:t('Participant sign in'),subtitle:t('Your classes, activities and progress are saved here.'),extra:`<p class="small muted">${esc(t('Ask your administrator for a participant account before requesting class admission.'))}</p>`});bindLogin(app,{requiredRole:'student',onSuccess:async u=>{state.user=u;await enter()},onLocaleChange:showLogin})}

async function enter(){state.stopEvents?.();state.stopEvents=eventSource(()=>refresh());setInterval(()=>api('/api/heartbeat',{method:'POST'}).catch(()=>{}),45000);await refresh();await flushOfflineResponses()}
async function refresh(){try{const [dash,settings,notes,record,tools,admissions]=await Promise.all([api(`/api/student/dashboard${state.selectedClass?`?class_id=${state.selectedClass}`:''}`),api('/api/public-settings'),api('/api/notifications').catch(()=>({notifications:[],unread:0})),api('/api/student/transcript').catch(()=>({transcript:[],certificates:[]})),api('/api/student/learning-tools').catch(()=>({surveys:[],quizzes:[],waitlist:[]})),api('/api/student/join-requests')]);state.admissions=admissions.requests||[];state.data=dash;state.user=dash.user;if(dash.active_class_id){state.selectedClass=Number(dash.active_class_id);localStorage.setItem('training_engine_student_live_class',String(state.selectedClass))}state.brand=settings?.brand?.name||'Training Engine ONE';state.settings=settings;state.notifications=notes.notifications||[];state.unread=notes.unread||0;state.transcript=record;state.learningTools=tools;applyTypography(mergeTypography(settings?.typography||{},dash?.active?.course?.branding?.typography||{}),'ui');render()}catch(e){if(e.status===401)return showLogin();toast(e.message,'error')}}
function currentHero(d){
  const live=d.active,item=live?.item,cl=live?.class,latest=d.classes?.[0];
  if(live&&item){const c=item.content||{};return {eyebrow:cl?.course_title||live.course?.title||'',title:c.hero_word||cl?.title||'',subtitle:c.hero_subtitle||t('Stay with your class. Your current task is below.'),active:true,dir:live.course?.direction||'ltr'}}
  if(live&&cl)return {eyebrow:cl.course_title,title:cl.title,subtitle:t('Your trainer will open the next activity when it is time to participate.'),active:true,dir:live.course?.direction||'ltr'};
  if(latest)return {eyebrow:latest.course_title,title:latest.title,subtitle:t('Your learning space is ready.'),active:false,dir:latest.direction||'auto'};
  return {eyebrow:t('Welcome'),title:t('Start learning'),subtitle:t('Your courses will appear here when you are enrolled.'),active:false,dir:'auto'};
}
const responseDrafts=new Map();
function captureResponseDraft(){const form=document.querySelector('#responseForm'),key=form?.dataset.draftKey;if(!key)return;responseDrafts.set(key,{submissionId:form.dataset.submissionId,fields:[...form.elements].filter(e=>e.name&&e.type!=='file').map(e=>({name:e.name,type:e.type,value:e.value,checked:e.checked}))});if(responseDrafts.size>50)responseDrafts.delete(responseDrafts.keys().next().value)}
function restoreResponseDraft(){const form=document.querySelector('#responseForm'),live=state.data?.active;if(!form||!live)return;const key=`${state.user.id}:${live.class.id}:${live.instance?.id||live.state?.payload?.instance_id}`;form.dataset.draftKey=key;const draft=responseDrafts.get(key);if(!draft)return;if(draft.submissionId)form.dataset.submissionId=draft.submissionId;const groups=new Map();for(const field of draft.fields){const i=groups.get(field.name)||0,controls=[...form.elements].filter(e=>e.name===field.name&&e.type===field.type);groups.set(field.name,i+1);const control=controls[i];if(!control)continue;if(['radio','checkbox'].includes(field.type))control.checked=field.checked;else control.value=field.value}}
function render(){
  captureResponseDraft();
  clearInterval(state.timerId);state.timerId=null;
  document.title=`Training Engine ONE — ${t('Participant')}`;const d=state.data,u=d.user,pMap=new Map((d.progress||[]).map(x=>[x.class_id,x])),hero=currentHero(d);
  app.innerHTML=`<div class="student-app"><header class="student-top"><div class="brand">${systemLogo()}<span>${esc(state.brand)}</span></div><div class="topbar-actions"><button class="btn primary" data-action="join-class">${uiIcon('add')}<span>${esc(t('Join class'))}</span></button><button class="btn icon notification-bell" data-action="notifications" aria-label="${esc(t('Notifications'))}">${uiIcon('bell')}${state.unread?`<span class="notification-count">${state.unread}</span>`:''}</button>${actionMenu(u.display_name||u.username,`<div class="one-menu-profile"><span class="avatar">${esc((u.display_name||u.username||'?').slice(0,1).toUpperCase())}</span><div><strong><bdi>${esc(u.display_name||u.username)}</bdi></strong><small>${esc(t('Participant'))}</small></div></div><button class="one-menu-item" data-action="profile">${uiIcon('user')}<span>${esc(t('My profile'))}</span></button><button class="one-menu-item" data-action="response-queue">${esc(t('Saved responses'))}<small>${readOfflineQueue().filter(r=>!r.student_id||Number(r.student_id)===Number(state.user.id)).length}</small></button><button class="one-menu-item" data-action="change-password">${esc(t('Change password'))}</button><div class="one-menu-separator"></div>${appearanceActions()}<div class="one-menu-separator"></div><button class="one-menu-item danger" data-action="logout">${esc(t('Sign out'))}</button>`,{icon:'user',compact:true})}</div></header>
  <main class="student-main student-main-wide">
    <section class="student-hero ${hero.active?'is-live':''}" dir="${hero.dir}"><div class="student-hero-overlay"><div class="hero-eyebrow">${esc(hero.eyebrow)}</div><h1>${esc(hero.title||'')}</h1>${hero.subtitle?`<p>${esc(hero.subtitle)}</p>`:''}${hero.active?`<div class="hero-live-dot"><span></span>${esc(t('Live with your class'))}</div>`:''}</div></section>
    ${d.active_classes?.length>1?`<section class="student-live-switcher"><div><strong>${esc(t('Live classes'))}</strong><span class="small muted">${esc(t('Choose the class you are following now.'))}</span></div><div class="topbar-actions">${d.active_classes.map(cl=>`<button class="btn ${Number(cl.id)===Number(d.active_class_id)?'primary':''}" data-live-class="${cl.id}">${esc(cl.title)}</button>`).join('')}</div></section>`:''}
    ${renderAdmissionRequests()}
    ${d.active?renderLivePanel(d.active):''}
    <section class="learning-section" id="your-learning"><div class="learning-head"><div><div class="eyebrow">${esc(t('Your learning'))}</div><h2>${esc(t('Keep moving forward'))}</h2><p>${esc(t('Your progress and activity remain available after every class.'))}</p></div><div class="learning-summary">${summaryPills(d.progress||[])}</div></div>
      <div class="learning-grid">${d.classes.length?d.classes.map(cl=>renderClassCard(cl,pMap.get(cl.id)||{},d.active?.class?.id)).join(''):`<div class="card"><div class="empty">${esc(t('You are not enrolled in a class yet.'))}</div></div>`}</div>
    </section>
    ${renderUpcoming(d.sessions||[])}${renderLearningTools()}${renderTranscript()}${renderFeedback(d.submissions||[])}
    <section class="activity-section"><div class="section-title-row"><div><div class="eyebrow">${esc(t('My activity'))}</div><h2>${esc(t('Recent learning activity'))}</h2></div></div><div class="activity-timeline">${d.recent.length?d.recent.map(ev=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${esc(humanEvent(ev.event_type))}</strong><div class="small muted">${esc(ev.class_title||'')}</div></div><time>${fmtDateTime(ev.created_at)}</time></div>`).join(''):`<div class="empty">${esc(t('Your activity will appear here.'))}</div>`}</div></section>
  </main></div>`;bind();bindMetricDrilldowns(app,row=>{location.href=`/profile?class_id=${row.id}`});
}
function renderAdmissionRequests(){const requests=(state.admissions||[]).filter(row=>row.status!=='approved');return requests.length?`<section class="admission-status-card card" role="status"><h2>${esc(t('Admission requests'))}</h2><div class="list">${requests.map(row=>`<div class="list-row"><div><strong dir="auto">${esc(row.class_title)}</strong><p class="small muted">${esc(t(row.status==='pending'?'Waiting for trainer approval.':row.status==='rejected'?'Admission declined.':'Class admission cancelled'))}</p>${row.note?`<p dir="auto">${esc(row.note)}</p>`:''}</div><span class="badge">${esc(t(row.status==='pending'?'Pending':row.status==='rejected'?'Rejected':'Cancelled'))}</span></div>`).join('')}</div></section>`:''}
function summaryPills(progress){const p=progress.reduce((a,x)=>({missions:a.missions+Number(x.missions||0),responses:a.responses+Number(x.responses||0),achievements:a.achievements+Number(x.achievements||0)}),{missions:0,responses:0,achievements:0});return `<span><strong>${p.missions}</strong>${esc(t('Missions'))}</span><span><strong>${p.responses}</strong>${esc(t('Activities'))}</span><span><strong>${p.achievements}</strong>${esc(t('Achievements'))}</span>`}
function renderClassCard(cl,p,activeId){const total=Number(p.responses||0)+Number(p.missions||0);return `<article class="learning-card" dir="${cl.direction||'auto'}"><div class="learning-card-top"><span class="status-dot ${cl.id===activeId?'on':''}"></span><span>${esc(cl.id===activeId?t('In progress'):uiStatus(cl.status))}</span></div><h3>${esc(cl.title)}</h3><p>${esc(cl.course_title)}</p><div class="learning-evidence-label">${esc(t(total?'Your participation so far':'Ready to begin'))}</div><div class="learning-metrics"><span><strong>${Number(p.missions||0)}</strong>${esc(t('Missions'))}</span><span><strong>${Number(p.responses||0)}</strong>${esc(t('Activities'))}</span><span><strong>${Number(p.score||0)}</strong>${esc(t('Score'))}</span></div><div class="metric-row"><div class="small muted">${fmtDate(cl.start_date)}</div><a class="btn" href="${esc(downloadUrl(`/api/classes/${cl.id}/calendar.ics`))}" target="_blank">${esc(t('Calendar'))}</a></div></article>`}
function renderUpcoming(rows){const now=new Date().toISOString().slice(0,10),up=rows.filter(x=>!x.session_date||String(x.session_date)>=now).slice(0,8);if(!up.length)return '';return `<section class="activity-section"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Schedule'))}</div><h2>${esc(t('Upcoming sessions'))}</h2></div></div><div class="learning-grid">${up.map(x=>`<article class="card"><span class="badge">${esc(x.class_title||t('Class'))}</span><h3>${esc(x.title||t('Session'))}</h3><p class="muted">${esc(x.session_date||'')} · ${esc(x.start_time||'')}${x.end_time?` – ${esc(x.end_time)}`:''}</p>${x.notes?`<div class="small">${esc(x.notes)}</div>`:''}</article>`).join('')}</div></section>`}
function renderFeedback(rows){const reviewed=rows.filter(x=>x.review_status&&x.review_status!=='pending').slice(0,8);if(!reviewed.length)return '';return `<section class="activity-section"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Trainer feedback'))}</div><h2>${esc(t('Reviewed work'))}</h2></div></div><div class="learning-grid">${reviewed.map(x=>`<article class="card"><div class="metric-row"><strong>${esc(x.class_title||t('Class'))}</strong><span class="badge">${esc(t(x.review_status==='revise'?'Revise':'Reviewed'))}</span></div><p>${esc(x.review_feedback||t('Your trainer reviewed this submission.'))}</p>${x.review_score!=null?`<div class="stat-value small-score">${Number(x.review_score)}${x.review_max_score!=null?` / ${Number(x.review_max_score)}`:''}</div>`:''}<div class="tiny muted">${fmtDateTime(x.reviewed_at||x.created_at)}</div></article>`).join('')}</div></section>`}
function joinClass(){modal(t('Join class'),`<p class="muted">${esc(t('Enter the six-character class code shown by your trainer.'))}</p><div class="field"><label>${esc(t('Class code'))}</label><input class="input join-code-input" name="code" maxlength="8" autocomplete="off" style="text-transform:uppercase" placeholder="ABC234"></div>`,{confirmText:t('Send request'),onConfirm:async w=>{const code=w.querySelector('[name=code]').value.trim().toUpperCase();if(!code)return false;const r=await api('/api/student/join',{method:'POST',json:{code}});if(r.pending){toast(t('Admission requested. Waiting for trainer approval.'),'success');await refresh();return}state.selectedClass=Number(r.class.id);localStorage.setItem('training_engine_student_live_class',String(state.selectedClass));toast(t('You joined the class.'),'success');await refresh()}})}
function renderLivePanel(live){const item=live.item,stateLive=live.state,dir=live.course?.direction||'ltr',mode=live.delivery?.delivery_mode||'trainer_paced';if(mode==='front_of_room')return `<section class="live-panel waiting"><div><div class="eyebrow">${esc(t('Front-of-Room mode'))}</div><h2>${esc(t('Follow the main screen'))}</h2><p>${esc(t('This class is being facilitated from the shared display. Personal responses are paused.'))}</p></div></section>`;if(stateLive.phase==='practice'&&item)return renderPersonalPractice(live);if(stateLive.phase==='waiting'||!item)return `<section class="live-panel waiting"><div><div class="eyebrow">${esc(t('Class in progress'))}</div><h2>${esc(t('Follow the main screen'))}</h2><p>${esc(t('Your trainer will open an activity when it is time for you to participate.'))}</p></div></section>`;if(stateLive.phase==='mission')return renderMission(live,item);const pace=mode==='participant_paced'?`<div class="metric-row participant-pace-nav"><button class="btn" data-paced="previous" ${live.self_paced?.previous?'':'disabled'}>← ${esc(t('Previous'))}</button><span class="delivery-badge">${esc(t('Participant-Paced'))} · ${Number(live.self_paced?.index||0)+1}/${Number(live.self_paced?.total||1)}</span><button class="btn" data-paced="next" ${live.self_paced?.next?'':'disabled'}>${esc(t('Next'))} →</button></div>`:'';
  const displayedContent={...(item.content||{heading:item.title})};if(displayedContent.heading===item.title)delete displayedContent.heading;if(displayedContent.question===item.title)delete displayedContent.question;
  return `<section class="live-panel" dir="${dir}"><div class="live-panel-head"><div><div class="eyebrow">${esc(live.class.title)}</div><h2>${esc(item.title||t('Activity'))}</h2></div><span class="live-pulse"><i></i>${esc(mode==='participant_paced'?t('Participant-Paced'):t('Live'))}</span></div>${pace}${stateLive.payload?.challenge?.enabled?`<div class="challenge-banner"><strong>${esc(t('Challenge'))}</strong><span>${esc(t('{n} seconds',{n:Number(stateLive.payload.challenge.time_seconds||0)}))} · ${esc(t('{n} bonus points',{n:Number(stateLive.payload.challenge.points||0)}))}</span></div>`:''}<div class="live-content">${renderContent(displayedContent,{versionId:live.class.course_version_id})}${live.personal_response?.submitted&&['activity','presentation'].includes(stateLive.phase)?`<div class="response-saved-state" role="status"><strong>✓ ${esc(t('Response submitted'))}</strong><span>${esc(t('You can update it until responses close.'))}</span></div>`:''}${renderResponseArea(live,item)}</div></section>`;
}

function advancedResponseForm(live,item,model){const c=item.content||{},sid=globalThis.crypto?.randomUUID?.()||`adv_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  if(model==='point_allocation'){const x={budget:100,max_per_option:100,...(item.prioritization||{})},opts=(c.options||[]).map(o=>typeof o==='string'?o:o.label||o.title||'');return `<form id="responseForm" class="response-form prioritization-response" data-submission-id="${esc(sid)}"><div class="word-cloud-response-head"><strong>${esc(c.question||t('Distribute your points'))}</strong><small>${esc(t('Allocate exactly {n} points.',{n:Number(x.budget||100)}))}</small></div><div class="point-allocation-list">${opts.map(o=>`<label class="point-allocation-row"><span>${esc(o)}</span><input class="input" type="number" min="0" max="${Number(x.max_per_option||x.budget||100)}" name="point" data-option="${esc(o)}" value="0"><strong data-point-value="${esc(o)}">0</strong></label>`).join('')}</div><div class="allocation-total"><span>${esc(t('Allocated'))}</span><strong data-allocation-total>0 / ${Number(x.budget||100)}</strong></div><button class="btn primary large-action" type="submit">${esc(t('Submit priorities'))}</button></form>`}
  if(model==='quick_choice'){const opts=(c.options||[]).length?c.options:['Yes','No'];return `<form id="responseForm" class="response-form quick-interaction-response" data-submission-id="${esc(sid)}"><div class="quick-pulse-grid">${opts.map(o=>`<label class="quick-pulse"><input type="radio" name="choice" value="${esc(typeof o==='string'?o:o.value||o.label||'')}" required><span>${esc(typeof o==='string'?o:o.label||o.value||'')}</span></label>`).join('')}</div><button class="btn primary large-action" type="submit">${esc(t('Send response'))}</button></form>`}
  if(model==='matching'){const pairs=item.matching?.pairs||c.pairs||[],rights=[...(item.matching?.choices||pairs.map(x=>x.right||x.answer||''))];return `<form id="responseForm" class="response-form matching-response" data-submission-id="${esc(sid)}">${pairs.map((x,i)=>`<div class="field"><label>${esc(x.left||x.prompt||`Item ${i+1}`)}</label><select class="select" name="match" data-key="${esc(x.id||`p${i+1}`)}" required><option value="">—</option>${rights.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('')}</select></div>`).join('')}<button class="btn primary large-action" type="submit">${esc(t('Submit matches'))}</button></form>`}
  if(model==='fill_blanks'){const blanks=item.fill_blanks?.blanks||c.blanks||[];return `<form id="responseForm" class="response-form fill-blanks-response" data-submission-id="${esc(sid)}">${blanks.map((b,i)=>`<div class="field"><label>${esc(b.label||b.prompt||t('Blank {n}',{n:i+1}))}</label><input class="input" name="blank" data-key="${esc(b.id||`b${i+1}`)}" autocomplete="off" required></div>`).join('')}<button class="btn primary large-action" type="submit">${esc(t('Submit answers'))}</button></form>`}
  if(model==='sorting'){const items=item.sorting?.items||c.items||[];return `<form id="responseForm" class="response-form sorting-response" data-submission-id="${esc(sid)}"><div class="ranking-input">${items.map((o,i)=>`<div><span>${esc(o)}</span><select class="select" name="sort_rank" data-label="${esc(o)}">${items.map((_,j)=>`<option value="${j+1}" ${j===i?'selected':''}>${j+1}</option>`).join('')}</select></div>`).join('')}</div><button class="btn primary large-action" type="submit">${esc(t('Submit order'))}</button></form>`}
  if(model==='image_interaction'){const x=item.image_interaction||{},asset=x.asset||c.image_asset||'',src=asset?`/api/assets/${Number(live.class.course_version_id)}/${String(asset).replace(/^asset:\/\//,'').split('/').map(encodeURIComponent).join('/')}`:'',mode=x.mode||'pin',targets=Array.isArray(x.targets)?x.targets:[],needsLabel=['label','drag'].includes(mode);return `<form id="responseForm" class="response-form image-interaction-response" data-submission-id="${esc(sid)}">${needsLabel&&targets.length?`<div class="image-label-palette"><label>${esc(t(mode==='drag'?'Drag a label onto the image':'Choose a label, then place it'))}</label><select class="select" data-image-label-select>${targets.map(z=>`<option value="${esc(z.label)}">${esc(z.label)}</option>`).join('')}</select>${mode==='drag'?`<div class="image-drag-labels">${targets.map(z=>`<button type="button" class="image-drag-token" draggable="true" data-image-drag-label="${esc(z.label)}">${esc(z.label)}</button>`).join('')}</div>`:''}</div>`:''}<div class="image-interaction-stage" data-image-stage data-mode="${esc(mode)}" ${src?`style="background-image:url('${esc(src)}')"`:''}><div class="image-interaction-help">${esc(t(mode==='find'?'Find the requested location on the image.':mode==='drag'?'Drag each label to its location, or click to place the selected label.':needsLabel?'Place the selected label on the image.':'Click the image to place your answer.'))}</div></div><input type="hidden" name="image_points" value="[]"><div class="form-actions"><button class="btn" type="button" data-clear-image-points>${esc(t('Clear'))}</button><button class="btn primary" type="submit">${esc(t('Submit image answer'))}</button></div></form>`}
  if(model==='drawing'){const x=item.draw_annotate||{},asset=x.asset||c.image_asset||'',src=asset?`/api/assets/${Number(live.class.course_version_id)}/${String(asset).replace(/^asset:\/\//,'').split('/').map(encodeURIComponent).join('/')}`:'';return `<form id="responseForm" class="response-form drawing-response" data-submission-id="${esc(sid)}"><div class="small muted">${esc(t(x.allow_text===false?'Draw directly on the canvas.':'Draw directly. Shift-click anywhere to add a text label.'))}</div><div class="drawing-stage-wrap" ${src?`style="background-image:url('${esc(src)}')"`:''}><canvas data-drawing-canvas width="900" height="520" data-allow-text="${x.allow_text===false?'0':'1'}"></canvas></div><input type="hidden" name="drawing_json" value='{"strokes":[],"labels":[]}'><div class="form-actions"><button class="btn" type="button" data-clear-drawing>${esc(t('Clear'))}</button><button class="btn primary" type="submit">${esc(t('Submit annotation'))}</button></div></form>`}
  if(model==='collab_board'){const x={categories:['Board'],max_characters:240,...(item.collaborative_board||{})};return `<form id="responseForm" class="response-form collaborative-response" data-submission-id="${esc(sid)}"><textarea class="answer-box" name="text" maxlength="${Number(x.max_characters||240)}" placeholder="${esc(t('Add a note…'))}" required></textarea>${x.categories?.length>1?`<select class="select" name="category">${x.categories.map(cat=>`<option value="${esc(cat)}">${esc(cat)}</option>`).join('')}</select>`:`<input type="hidden" name="category" value="${esc(x.categories?.[0]||'Board')}">`}<button class="btn primary large-action" type="submit">${esc(t('Add to board'))}</button></form>`}
  if(model==='video_checkpoints'){const x=item.interactive_video||{},asset=x.asset||c.video_asset||'',src=asset?`/api/assets/${Number(live.class.course_version_id)}/${String(asset).replace(/^asset:\/\//,'').split('/').map(encodeURIComponent).join('/')}`:'';return `<form id="responseForm" class="response-form interactive-video-response" data-submission-id="${esc(sid)}">${src?`<video class="content-video" controls data-interactive-video src="${esc(src)}"></video>`:''}<div class="video-checkpoints">${(x.checkpoints||[]).map(cp=>`<div class="video-checkpoint" data-checkpoint="${esc(cp.id)}" data-time="${Number(cp.time_seconds||0)}"><strong>${esc(cp.prompt||'')}</strong>${cp.type==='single_choice'?`<div class="choice-grid">${(cp.options||[]).map(o=>`<label class="choice"><input type="radio" name="cp_${esc(cp.id)}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join('')}</div>`:cp.type==='confidence'?`<select class="select" name="cp_${esc(cp.id)}">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select>`:`<input class="input" name="cp_${esc(cp.id)}">`}</div>`).join('')}</div><button class="btn primary large-action" type="submit">${esc(t('Submit video responses'))}</button></form>`}
  return '';
}
const OFFLINE_QUEUE_KEY='training_engine_response_queue_v1';
function readOfflineQueue(){try{const rows=JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||'[]');return Array.isArray(rows)?rows:[]}catch{return []}}
function writeOfflineQueue(q){localStorage.setItem(OFFLINE_QUEUE_KEY,JSON.stringify(q))}
