function renderMissionSubmission(sub,live){const type=sub.type||'text';if(type==='none')return `<button class="btn primary large-action" id="completeMission" type="button">${esc(t('Complete mission'))}</button>`;if(type==='url')return `<form id="missionForm"><div class="field"><label>${esc(sub.prompt||t('Share your result link'))}</label><input class="input" type="url" name="value" required></div><button class="btn primary large-action">${esc(t('Complete mission'))}</button></form>`;if(type==='file'||type==='image')return `<form id="missionForm"><div class="field"><label>${esc(sub.prompt||t('Upload your result'))}</label><input class="input" type="file" name="file" ${type==='image'?'accept="image/*"':''} required></div><button class="btn primary large-action">${esc(t('Complete mission'))}</button></form>`;return `<form id="missionForm"><div class="field"><label>${esc(sub.prompt||t('What did you learn?'))}</label><textarea class="textarea" name="value" required></textarea></div><button class="btn primary large-action">${esc(t('Complete mission'))}</button></form>`}
function formatTime(s){s=Math.max(0,Number(s)||0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`}

function renderLearningTools(){const x=state.learningTools||{},surveys=x.surveys||[],quizzes=x.quizzes||[],wait=x.waitlist||[];if(!surveys.length&&!quizzes.length&&!wait.length)return '';return `<section class="activity-section"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Learning tools'))}</div><h2>${esc(t('Continue your course work'))}</h2></div></div><div class="learning-grid">${surveys.map(s=>`<article class="card"><span class="badge">${esc(t('Evaluation'))}</span><h3>${esc(s.title)}</h3><p class="muted">${esc(s.class_title||'')}</p><button class="btn primary" data-survey="${s.id}">${esc(t('Complete evaluation'))}</button></article>`).join('')}${quizzes.map(q=>`<article class="card"><span class="badge">${esc(t('Knowledge check'))}</span><h3>${esc(q.title)}</h3><p class="muted">${esc(q.class_title||'')} · ${q.question_count} ${esc(t('questions'))}</p>${q.submitted_at?`<div class="stat-value small-score">${Number(q.score||0)} / ${Number(q.max_score||0)}</div>`:`<button class="btn primary" data-quiz="${q.id}">${esc(t('Start quiz'))}</button>`}</article>`).join('')}${wait.map(w=>`<article class="card"><span class="badge">${esc(t('Waitlist'))}</span><h3>${esc(w.class_title)}</h3><p>${esc(t('You are on the waitlist.'))}</p><div class="stat-value small-score">#${Number(w.position||0)}</div></article>`).join('')}</div></section>`}
function renderTranscript(){const r=state.transcript||{},rows=r.transcript||[],certs=r.certificates||[];if(!rows.length&&!certs.length)return '';return `<section class="activity-section"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Learning record'))}</div><h2>${esc(t('Your transcript & accomplishments'))}</h2></div><a class="btn" href="${downloadUrl('/api/student/transcript.csv')}" download>${esc(t('Download transcript'))}</a></div><div class="learning-grid">${rows.slice(0,8).map(x=>`<article class="card"><span class="badge">${esc(t(x.completion_status==='completed'?'Completed':'In progress'))}</span><h3>${esc(x.course_title)}</h3><p class="muted">${esc(x.class_title)} · v${esc(x.version)}</p><div class="progress"><span style="width:${Math.max(0,Math.min(100,Number(x.completion_percent||0)))}%"></span></div><div class="small">${Number(x.completion_percent||0)}%</div></article>`).join('')}${certs.map(c=>`<article class="card certificate-card"><span class="badge ok">${esc(t('Certificate'))}</span><h3>${esc(c.title)}</h3><p class="muted">${esc(c.course_title||'')} · ${fmtDateTime(c.issued_at)}</p><div class="tiny">${esc(t('Verification code'))}: <strong>${esc(c.verification_code)}</strong></div><a class="btn primary" href="/certificate?code=${encodeURIComponent(c.verification_code)}" target="_blank">${esc(t('Open certificate'))}</a></article>`).join('')}</div></section>`}
async function openSurvey(id){const s=(state.learningTools?.surveys||[]).find(x=>Number(x.id)===Number(id));if(!s)return;const qs=s.definition?.questions||[];modal(s.title,`<div class="survey-form">${qs.map(q=>`<div class="field"><label>${esc(q.prompt||q.title||q.id)}</label>${q.type==='rating'?`<select class="select" data-survey-answer="${esc(q.id)}">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}</option>`).join('')}</select>`:`<textarea class="textarea" data-survey-answer="${esc(q.id)}"></textarea>`}</div>`).join('')}</div>`,{confirmText:t('Submit evaluation'),onConfirm:async w=>{const response={};w.querySelectorAll('[data-survey-answer]').forEach(el=>response[el.dataset.surveyAnswer]=el.value);await api(`/api/surveys/${id}/respond`,{method:'POST',json:{response}});toast(t('Evaluation submitted.'),'success');await refresh()}})}
async function openQuiz(id){const d=await api(`/api/quizzes/${id}/attempt`);if(d.submitted_at){toast(`${t('Score')}: ${d.score} / ${d.max_score}`,'success');return}modal(d.quiz.title,`<div class="quiz-form">${d.questions.map((q,i)=>`<div class="card flat"><div class="eyebrow">${esc(t('Question'))} ${i+1}</div><h3>${esc(q.prompt)}</h3>${q.question_type==='single_choice'||q.question_type==='true_false'?`<div class="selection-grid">${(q.options||[]).map(o=>`<label class="select-card"><input type="radio" name="quiz_${q.id}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join('')}</div>`:q.question_type==='multiple_choice'?`<div class="selection-grid">${(q.options||[]).map(o=>`<label class="select-card"><input type="checkbox" data-quiz-multi="${q.id}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join('')}</div>`:`<input class="input" data-quiz-text="${q.id}">`}</div>`).join('')}</div>`,{wide:true,confirmText:t('Submit quiz'),onConfirm:async w=>{const answers={};for(const q of d.questions){if(q.question_type==='multiple_choice')answers[q.id]=[...w.querySelectorAll(`[data-quiz-multi="${q.id}"]:checked`)].map(x=>x.value);else if(q.question_type==='single_choice'||q.question_type==='true_false')answers[q.id]=w.querySelector(`[name="quiz_${q.id}"]:checked`)?.value??'';else answers[q.id]=w.querySelector(`[data-quiz-text="${q.id}"]`)?.value??''}const r=await api(`/api/quizzes/${id}/attempt`,{method:'POST',json:{answers}});toast(`${t('Score')}: ${r.score} / ${r.max_score}`,'success');await refresh()}})}

function restoreOwnResponse(){
  const own=state.data?.active?.personal_response,form=document.querySelector('#responseForm');if(!own?.submitted||!form)return;
  const answer=own.answer,button=form.querySelector('[type=submit]');if(button)button.textContent=t('Update response');
  for(const el of form.querySelectorAll('[name]')){
    if(el.name==='match'&&answer&&typeof answer==='object')el.value=answer[el.dataset.key]??'';
    else if(el.name==='blank'&&answer&&typeof answer==='object')el.value=answer[el.dataset.key]??'';
    else if(el.name==='sort_rank'&&Array.isArray(answer))el.value=String(answer.indexOf(el.dataset.label)+1);
    else if(el.name==='choice')el.checked=String(el.value)===String(answer);
    else if(el.type==='checkbox'&&Array.isArray(answer))el.checked=answer.map(String).includes(el.value);
    else if(['answer','text','url','number','rating'].includes(el.name)&&['string','number'].includes(typeof answer))el.value=String(answer);
  }
}
function bind(){restoreOwnResponse();restoreResponseDraft();document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',async()=>{const a=b.dataset.action;if(a==='theme'){cycleTheme();render()}else if(a==='language'){cycleLocale();render()}else if(a==='response-queue')showResponseQueue();else if(a==='profile')location.href='/profile';else if(a==='notifications')showNotifications();else if(a==='join-class')joinClass();else if(a==='logout'){await api('/api/logout',{method:'POST'}).catch(()=>{});setToken('');showLogin()}else if(a==='change-password')changePassword()}));document.querySelectorAll('[data-paced]').forEach(b=>b.addEventListener('click',async()=>{const live=state.data.active;if(!live)return;await api(`/api/student/paced/${live.class.id}/navigate`,{method:'POST',json:{direction:b.dataset.paced}});await refresh()}));document.querySelectorAll('[data-live-class]').forEach(b=>b.addEventListener('click',async()=>{state.selectedClass=Number(b.dataset.liveClass);localStorage.setItem('training_engine_student_live_class',String(state.selectedClass));await refresh()}));document.querySelectorAll('[data-path]').forEach(b=>b.addEventListener('click',()=>choosePath(b.dataset.path)));document.querySelectorAll('[data-step-nav]').forEach(b=>b.addEventListener('click',()=>moveStep(b.dataset.stepNav)));document.querySelector('[data-help]')?.addEventListener('click',requestHelp);document.querySelectorAll('[data-survey]').forEach(b=>b.addEventListener('click',()=>openSurvey(Number(b.dataset.survey))));document.querySelectorAll('[data-quiz]').forEach(b=>b.addEventListener('click',()=>openQuiz(Number(b.dataset.quiz))));document.querySelector('[data-copy-guided]')?.addEventListener('click',async e=>{const text=document.querySelector('#guidedPrompt')?.value||'';try{await navigator.clipboard.writeText(text);toast(t('Copied.'),'success')}catch{toast(t('Copy the prompt manually.'),'error')}});document.querySelectorAll('[data-qa-vote]').forEach(b=>b.addEventListener('click',()=>toggleQaVote(b)));document.querySelectorAll('[data-idea-vote]').forEach(b=>b.addEventListener('click',()=>toggleIdeaVote(b)));const rf=document.querySelector('#responseForm');if(rf)rf.addEventListener('submit',submitResponse);bindAdvancedResponse();const mf=document.querySelector('#missionForm');if(mf)mf.addEventListener('submit',submitMission);document.querySelector('#completeMission')?.addEventListener('click',()=>completeMissionNoSubmission());document.querySelectorAll('[data-copy-prompt]').forEach(btn=>btn.addEventListener('click',async()=>{const idx=Number(btn.dataset.copyPrompt),p=state.data.active?.item?.prompts?.[idx],text=p?.text||p||'';try{await navigator.clipboard.writeText(String(text));toast(t('Copied.'),'success')}catch{toast(t('Copy the prompt manually.'),'error')}}));const timer=document.querySelector('[data-timer]');if(timer){let sec=Number(timer.dataset.timer);state.timerId=setInterval(()=>{sec--;timer.textContent=formatTime(sec);if(sec<=0){clearInterval(state.timerId);state.timerId=null}},1000)}}
async function toggleQaVote(btn){const live=state.data.active,iid=Number(live?.state?.payload?.instance_id||0);if(!iid||!live?.class?.id)return;const voted=btn.dataset.voted!=='1';btn.disabled=true;try{await api(`/api/live/${live.class.id}/q-and-a/${iid}/vote`,{method:'POST',json:{question_id:btn.dataset.qaVote,voted}});await refresh()}catch(e){toast(e.message,'error');btn.disabled=false}}
async function toggleIdeaVote(btn){const live=state.data.active,iid=Number(live?.state?.payload?.instance_id||0);if(!iid||!live?.class?.id)return;const voted=btn.dataset.voted!=='1';btn.disabled=true;try{await api(`/api/live/${live.class.id}/ideas-board/${iid}/vote`,{method:'POST',json:{idea_id:btn.dataset.ideaVote,voted}});await refresh()}catch(e){toast(e.message,'error');btn.disabled=false}}
async function submitResponse(e){e.preventDefault();const form=e.currentTarget,live=state.data.active,item=live?.item;if(!live||!item)return;const f=new FormData(form),model=activitySpec(item.type)?.response_model;let ans;if(model==='file'||model==='image'){const file=f.get('file');if(!file?.size)return;const up=await api(`/api/submissions/${live.class.id}`,{method:'POST',body:await file.arrayBuffer(),headers:{'X-Submission-Kind':model,'X-File-Name':encodeURIComponent(file.name),'X-Module-Id':live.state.module_id,'X-Activity-Id':live.state.activity_id}});ans={submission_id:up.id,name:up.name,size:up.size}}else if(model==='url')ans=f.get('url');else if(model==='checklist')ans=f.getAll('check');else if(model==='multiple_choice')ans=f.getAll('choice');else if(['single_choice','true_false'].includes(model))ans=f.get('choice');else if(model==='scale')ans=Number(f.get('rating'));else if(model==='number')ans=Number(f.get('number'));else if(model==='ranking'){ans={};const rankInputs=[...form.querySelectorAll('[name^="rank_"]')],rankValues=rankInputs.map(x=>Number(x.value));if(new Set(rankValues).size!==rankValues.length){toast(t('Use each rank exactly once.'),'error');return}rankInputs.forEach(x=>ans[x.dataset.label]=Number(x.value))}else if(model==='point_allocation'){ans={};form.querySelectorAll('[name="point"]').forEach(x=>ans[x.dataset.option]=Number(x.value||0))}else if(model==='quick_choice')ans=f.get('choice');else if(model==='matching'){ans={};form.querySelectorAll('[name="match"]').forEach(x=>ans[x.dataset.key]=x.value)}else if(model==='fill_blanks'){ans={};form.querySelectorAll('[name="blank"]').forEach(x=>ans[x.dataset.key]=x.value)}else if(model==='sorting'){const sortRows=[...form.querySelectorAll('[name="sort_rank"]')].map(x=>({label:x.dataset.label,rank:Number(x.value)}));if(new Set(sortRows.map(x=>x.rank)).size!==sortRows.length){toast(t('Use each rank exactly once.'),'error');return}ans=sortRows.sort((a,b)=>a.rank-b.rank).map(x=>x.label)}else if(model==='image_interaction'){try{ans={points:JSON.parse(f.get('image_points')||'[]')}}catch{ans={points:[]}}}else if(model==='drawing'){try{ans=JSON.parse(f.get('drawing_json')||'{"strokes":[]}')}catch{ans={strokes:[]}}}else if(model==='collab_board')ans={text:f.get('text'),category:f.get('category')};else if(model==='video_checkpoints'){ans={};for(const cp of item.interactive_video?.checkpoints||[])ans[cp.id]=f.get(`cp_${cp.id}`)}else if(model==='word_list')ans=f.getAll('word').map(x=>String(x||'').trim()).filter(Boolean);else if(model==='idea_board')ans={text:f.get('text'),category:f.get('category')};else ans=f.get('text');const btn=form.querySelector('button[type="submit"]');if(btn)btn.disabled=true;try{await api(`/api/responses/${live.state.payload.instance_id}`,{method:'POST',json:{answer:ans,client_submission_id:form.dataset.submissionId||null}});toast(t(item.type==='word_cloud'?'Word Cloud response saved.':item.type==='q_and_a'?'Question submitted.':item.type==='ideas_board'?'Idea submitted.':'Response saved.'),'success');await refresh()}catch(err){if(!err?.status){enqueueOfflineResponse({instance_id:live.state.payload.instance_id,answer:ans,client_submission_id:form.dataset.submissionId||null});toast(t('Connection lost. Your response is queued and will sync automatically.'),'success')}else toast(err.message,'error');if(btn)btn.disabled=false}}
async function completeMissionNoSubmission(){
 const live=state.data.active,button=document.querySelector('#completeMission');if(!live||!button)return;
 button.disabled=true;try{await api(`/api/missions/${live.class.id}/progress`,{method:'POST',json:{module_id:live.state.module_id,mission_id:live.state.activity_id,status:'completed',progress:{acknowledged:true}}});toast(t('Mission completed.'),'success');await refresh()}catch(error){toast(error.message,'error');if(button.isConnected)button.disabled=false}
}
async function submitMission(e){e.preventDefault();const live=state.data.active,classId=live.class.id,moduleId=live.state.module_id,missionId=live.state.activity_id,m=live.item,sub=m.submission||{type:'text'},f=new FormData(e.currentTarget),btn=e.currentTarget.querySelector('button');btn.disabled=true;try{if(sub.type==='file'||sub.type==='image'){const file=f.get('file');if(file?.size)await api(`/api/submissions/${classId}`,{method:'POST',body:await file.arrayBuffer(),headers:{'X-Submission-Kind':sub.type,'X-File-Name':encodeURIComponent(file.name),'X-Module-Id':moduleId,'X-Mission-Id':missionId}})}else await api(`/api/submissions/${classId}`,{method:'POST',json:{value:f.get('value')},headers:{'X-Submission-Kind':sub.type||'text','X-Module-Id':moduleId,'X-Mission-Id':missionId}});await api(`/api/missions/${classId}/progress`,{method:'POST',json:{module_id:moduleId,mission_id:missionId,status:'completed',progress:{submitted:true}}});toast(t('Mission completed.'),'success');await refresh()}catch(err){toast(err.message,'error');btn.disabled=false}}
function renderPersonalPractice(live){const item=live.item,ps=live.personal_state,path=live.personal_path;const choices=(item.paths?.length?item.paths:item.missions)||[];if(!ps?.path_id||!path){return `<section class="live-panel guided-activity" dir="${live.course?.direction||'ltr'}"><div class="live-panel-head"><div><div class="eyebrow">${esc(t('Personal practice'))}</div><h2>${esc(item.title||t('Choose a path'))}</h2><p>${esc(item.content?.body_short||t('Choose the activity you want to practice.'))}</p></div><span class="live-pulse"><i></i>${esc(t('Practice is open'))}</span></div><div class="content-cards">${choices.map(x=>`<article><h3>${esc(x.title||x.id)}</h3><p class="muted">${esc(x.goal||'')}</p><button class="btn primary" data-path="${esc(x.id)}">${esc(t('Start'))}</button></article>`).join('')}</div></section>`}const steps=path.steps||[],idx=Math.max(0,Math.min(steps.length-1,Number(ps.step_index||0))),step=steps[idx]||{};const prompt=step.prompt_template||step.prompt||'';return `<section class="live-panel guided-activity" dir="${live.course?.direction||'ltr'}"><div class="live-panel-head"><div><div class="eyebrow">${esc(path.title||t('Personal practice'))}</div><h2>${esc(step.title||`${t('Step')} ${idx+1}`)}</h2></div><span class="step-pill">${esc(t('Step {current} of {total}',{current:idx+1,total:steps.length}))}</span></div><div class="guided-progress"><div class="progress"><span style="width:${steps.length?((idx+1)/steps.length)*100:0}%"></span></div></div>${step.body_md?`<div class="rich">${md(step.body_md)}</div>`:''}${step.blocks?renderContent({blocks:step.blocks},{versionId:live.class.course_version_id}):''}${prompt?`<div class="prompt-template"><label class="strong">${esc(t('Prompt'))}</label><textarea class="textarea" id="guidedPrompt">${esc(typeof prompt==='string'?prompt:prompt.text||'')}</textarea><button class="btn" data-copy-guided>${esc(t('Copy prompt'))}</button></div>`:''}${(step.resources||[]).length?`<div class="resource-list">${step.resources.map(r=>`<a class="resource-link" href="${esc(r.url||'#')}" target="_blank" rel="noopener"><span>${esc(r.label||r.title||t('Open resource'))}</span><span>↗</span></a>`).join('')}</div>`:''}<div class="guided-actions"><button class="btn" data-step-nav="back" ${idx===0?'disabled':''}>← ${esc(t('Previous'))}</button><button class="btn need-help" data-help>${esc(t('NEED HELP'))}</button><button class="btn primary" data-step-nav="${idx>=steps.length-1?'finish':'next'}">${esc(idx>=steps.length-1?t('Finished'):t('Next'))} →</button></div>${ps.status==='need_help'?`<div class="content-callout warning"><div><strong>${esc(t('Help request sent.'))}</strong><div class="small">${esc(t('Your trainer can see where you are and will help without interrupting the class.'))}</div></div></div>`:''}</section>`}
async function choosePath(pathId){const live=state.data.active,choice=[...(live.item.paths||[]),...(live.item.missions||[])].find(x=>String(x.id)===String(pathId));if(!choice)return;await api(`/api/student/runtime/${live.class.id}`,{method:'PUT',json:{module_id:live.state.module_id,path_id:pathId,activity_id:choice.steps?.[0]?.id||null,step_index:0,step_total:(choice.steps||[]).length,status:'working',progress:{}}});await refresh()}
async function moveStep(dir){const live=state.data.active,ps=live.personal_state,path=live.personal_path,steps=path?.steps||[];let idx=Number(ps?.step_index||0);if(dir==='back')idx=Math.max(0,idx-1);else if(dir==='next')idx=Math.min(Math.max(0,steps.length-1),idx+1);const finished=dir==='finish';await api(`/api/student/runtime/${live.class.id}`,{method:'PUT',json:{module_id:live.state.module_id,path_id:path.id,activity_id:steps[idx]?.id||null,step_index:idx,step_total:steps.length,status:finished?'finished':'working',progress:{...(ps?.progress||{}),last_step:idx}}});toast(finished?t('Finished'):t('Continue'),'success');await refresh()}
async function requestHelp(){const live=state.data.active;if(!live)return;const msg=prompt(t('Need help')+' — '+t('Description'),'')||'';await api(`/api/student/runtime/${live.class.id}/help`,{method:'POST',json:{message:msg}});toast(t('Help request sent.'),'success');await refresh()}
function showNotifications(){modal(t('Notifications'),`<div class="notification-list">${state.notifications.map(n=>`<article class="notification-item ${n.read_at?'':'unread'}" data-note="${n.id}"><div class="metric-row"><strong>${esc(n.title)}</strong><span class="tiny muted">${fmtDateTime(n.created_at)}</span></div><div>${esc(n.body)}</div>${!n.read_at?`<button class="btn" data-read-note="${n.id}">${esc(t('Mark as read'))}</button>`:''}</article>`).join('')||`<div class="empty">${esc(t('No notifications yet.'))}</div>`}</div>`,{wide:true});setTimeout(()=>document.querySelectorAll('[data-read-note]').forEach(b=>b.addEventListener('click',async()=>{await api(`/api/notifications/${b.dataset.readNote}/read`,{method:'POST'});await refresh();b.closest('.modal-backdrop')?.remove()})),0)}
function editProfile(){api('/api/profile').then(d=>{const p=d.profile.profile||{},cons=Object.fromEntries((d.profile.consents||[]).map(x=>[x.consent_key,!!x.granted]));modal(t('My profile'),`<div class="profile-grid"><div class="field"><label>${esc(t('Username / ID'))}</label><input class="input" value="${esc(d.profile.username)}" disabled><div class="tiny muted">${esc(t('Your username cannot be changed.'))}</div></div><div class="field"><label>${esc(t('Email'))}</label><input class="input" name="email" type="email" value="${esc(d.profile.email||'')}" required></div><div class="field"><label>${esc(t('Full name in Arabic'))}</label><input class="input" name="full_name_ar" value="${esc(p.full_name_ar||'')}" required></div><div class="field"><label>${esc(t('Full name in English'))}</label><input class="input" name="full_name_en" value="${esc(p.full_name_en||d.profile.display_name||'')}" required></div><div class="field"><label>${esc(t('Mobile number'))}</label><input class="input" name="mobile" value="${esc(p.mobile||'')}" required></div><div class="field"><label>${esc(t('WhatsApp'))}</label><input class="input" name="whatsapp" value="${esc(p.whatsapp||'')}"></div><div class="field"><label>${esc(t('Telegram'))}</label><input class="input" name="telegram" value="${esc(p.telegram||'')}"></div><div class="field"><label>${esc(t('Organization'))}</label><input class="input" name="organization" value="${esc(p.organization||'')}"></div><div class="field"><label>${esc(t('Specialty'))}</label><input class="input" name="specialty" value="${esc(p.specialty||'')}"></div><div class="field"><label>${esc(t('Job title'))}</label><input class="input" name="job_title" value="${esc(p.job_title||'')}"></div><div class="field"><label>${esc(t('City'))}</label><input class="input" name="city" value="${esc(p.city||'')}"></div><div class="field"><label>${esc(t('Country'))}</label><input class="input" name="country" value="${esc(p.country||'')}"></div><div class="field span-2"><label>${esc(t('Learning goals'))}</label><textarea class="textarea" name="learning_goals">${esc(p.learning_goals||'')}</textarea></div><div class="consent-box span-2"><strong>${esc(t('Privacy & communication preferences'))}</strong><label><input type="checkbox" name="future_training" ${cons.future_training?'checked':''}> ${esc(t('Future training opportunities'))}</label><label><input type="checkbox" name="marketing" ${cons.marketing?'checked':''}> ${esc(t('Marketing communications'))}</label><label><input type="checkbox" name="testimonial" ${cons.testimonial?'checked':''}> ${esc(t('Testimonial permission'))}</label><label><input type="checkbox" name="photo_video" ${cons.photo_video?'checked':''}> ${esc(t('Photo/video permission'))}</label></div></div><div class="form-actions"><button class="btn" type="button" data-profile-password>${esc(t('Change password'))}</button><button class="btn danger" type="button" data-profile-logout>${esc(t('Sign out'))}</button></div>`,{confirmText:t('Update profile'),onConfirm:async w=>{const g=n=>w.querySelector(`[name="${n}"]`)?.value||'';const profile={...p,full_name_ar:g('full_name_ar').trim(),full_name_en:g('full_name_en').trim(),mobile:g('mobile').trim(),whatsapp:g('whatsapp'),telegram:g('telegram'),organization:g('organization'),specialty:g('specialty'),job_title:g('job_title'),city:g('city'),country:g('country'),learning_goals:g('learning_goals')};const email=g('email').trim();if(!profile.full_name_ar||!profile.full_name_en||!profile.mobile||!email){toast(t('Arabic name, English name, email and mobile number are required.'),'error');return false}await api('/api/profile',{method:'PATCH',json:{display_name:profile.full_name_en||profile.full_name_ar,email,profile,complete_profile:true,consents:{future_training:w.querySelector('[name=future_training]').checked,marketing:w.querySelector('[name=marketing]').checked,testimonial:w.querySelector('[name=testimonial]').checked,photo_video:w.querySelector('[name=photo_video]').checked}}});toast(t('Profile updated.'),'success');await refresh()}});setTimeout(()=>{document.querySelector('[data-profile-logout]')?.addEventListener('click',async()=>{await api('/api/logout',{method:'POST'}).catch(()=>{});setToken('');document.querySelector('.modal-backdrop')?.remove();showLogin()});document.querySelector('[data-profile-password]')?.addEventListener('click',()=>changePassword())},0)}).catch(e=>toast(e.message,'error'))}
function changePassword(){modal(t('Change password'),`<div class="field"><label>${esc(t('Current password'))}</label><input class="input" type="password" name="current"></div><div class="field" style="margin-top:12px"><label>${esc(t('New password'))}</label><input class="input" type="password" name="next"></div>`,{confirmText:t('Update password'),onConfirm:async w=>{await api('/api/account/password',{method:'POST',json:{current_password:w.querySelector('[name=current]').value,new_password:w.querySelector('[name=next]').value}});toast(t('Password updated.'),'success')}})}

window.addEventListener('online',()=>flushOfflineResponses().catch(error=>toast(error.message,'error')));
window.addEventListener('focus',()=>flushOfflineResponses().catch(error=>toast(error.message,'error')));
boot().catch(()=>showLogin());
